use std::time::{Duration, Instant};

/// A token bucket rate limiter.
///
/// Tokens are added at a fixed rate. Each request consumes one token.
/// If no tokens are available, the request is rejected.
pub struct TokenBucket {
    capacity: u32,
    tokens: f64,
    refill_rate: f64, // tokens per second
    last_refill: Instant,
}

impl TokenBucket {
    /// Create a new token bucket with the given capacity and refill rate (tokens per second).
    pub fn new(capacity: u32, refill_rate: f64) -> Self {
        assert!(capacity > 0, "Capacity must be greater than zero");
        assert!(refill_rate > 0.0, "Refill rate must be positive");
        Self {
            capacity,
            tokens: capacity as f64,
            refill_rate,
            last_refill: Instant::now(),
        }
    }

    /// Try to consume a single token.
    /// Returns `true` if a token was available and consumed, `false` otherwise.
    pub fn try_consume(&mut self) -> bool {
        self.refill();
        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }

    /// Refill tokens based on elapsed time since last refill.
    fn refill(&mut self) {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill);
        let elapsed_secs = elapsed.as_secs_f64();
        let new_tokens = elapsed_secs * self.refill_rate;
        self.tokens = (self.tokens + new_tokens).min(self.capacity as f64);
        self.last_refill = now;
    }
}

/// A clock abstraction for testing.
/// Allows injecting time into the rate limiter for deterministic testing.
pub trait Clock {
    fn now(&self) -> Instant;
}

/// A real clock that returns the current system time.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A test clock that allows manually advancing time.
pub struct TestClock {
    current: Instant,
}

impl TestClock {
    /// Create a new test clock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        Self { current: start }
    }

    /// Advance the clock by the given duration.
    pub fn advance(&mut self, duration: Duration) {
        self.current += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        self.current
    }
}

/// A clock-aware token bucket that uses a provided clock.
