    bool tryConsume(double n) {
        if (n < 0) {
            throw std::invalid_argument("n must be non-negative");
        }
        if (n == 0) {
            return true;
        }
        if (n > max_tokens_) {
            return false;
        }
        refill();
        if (tokens_ >= n) {
            tokens_ -= n;
            return true;
        }
