use std::collections::{BinaryHeap, HashMap, HashSet};
use std::cmp::Reverse;

type Graph = HashMap<String, Vec<(String, u64)>>;

fn dijkstra(graph: &Graph, start: &str, end: &str) -> Option<Vec<String>> {
    let mut distances: HashMap<String, u64> = HashMap::new();
    let mut previous: HashMap<String, Option<String>> = HashMap::new();
    let mut visited: HashSet<String> = HashSet::new();
    let mut heap: BinaryHeap<Reverse<(u64, String)>> = BinaryHeap::new();

    // Initialize distances
    for node in graph.keys() {
        distances.insert(node.clone(), u64::MAX);
    }
    distances.insert(start.to_string(), 0);
    previous.insert(start.to_string(), None);

    heap.push(Reverse((0, start.to_string())));

    while let Some(Reverse((dist, current_node))) = heap.pop() {
        if visited.contains(&current_node) {
            continue;
        }
        visited.insert(current_node.clone());

        if current_node == end {
            break;
        }

        if let Some(neighbors) = graph.get(&current_node) {
            for (neighbor, weight) in neighbors {
                if visited.contains(neighbor) {
                    continue;
                }
                let new_dist = dist + weight;
                if new_dist < *distances.get(neighbor).unwrap_or(&u64::MAX) {
                    distances.insert(neighbor.clone(), new_dist);
                    previous.insert(neighbor.clone(), Some(current_node.clone()));
                    heap.push(Reverse((new_dist, neighbor.clone())));
                }
            }
        }
    }

    // Reconstruct path
    if !distances.contains_key(end) || distances.get(end).unwrap_or(&u64::MAX) == &u64::MAX {
        return None;
    }

    let mut path = Vec::new();
    let mut current = end.to_string();
    while let Some(prev) = previous.get(&current) {
        path.push(current.clone());
        match prev {
            Some(p) => current = p.clone(),
            None => break,
        }
    }
    path.push(start.to_string());
    path.reverse();

    if path.is_empty() || path[0] != start || path[path.len() - 1] != end {
        return None;
    }

    Some(path)
}

