/// Represents a parsed CSV row as a vector of strings.
pub type CsvRow = Vec<String>;

/// A simple CSV reader that handles quoted fields (with double-quote escaping).
///
/// This function parses a single line of CSV data, respecting quoted fields
/// where commas and newlines inside quotes are treated as literal characters.
/// Double quotes inside a quoted field are escaped by doubling them (e.g., `""`).
pub fn parse_csv_line(line: &str) -> CsvRow {
    let mut fields = Vec::new();
    let mut chars = line.chars().peekable();
    let mut current_field = String::new();
    let mut in_quotes = false;

    loop {
        match chars.next() {
            Some('"') => {
                if in_quotes {
                    // Check if next char is also a quote (escaped quote)
                    if chars.peek() == Some(&'"') {
                        current_field.push('"');
                        chars.next(); // consume the second quote
                    } else {
                        // End of quoted section
                        in_quotes = false;
                    }
                } else {
                    // Start of quoted section
                    in_quotes = true;
                }
            }
            Some(',') => {
                if in_quotes {
                    current_field.push(',');
                } else {
                    // End of field
                    fields.push(current_field.clone());
                    current_field.clear();
                }
            }
            Some(c) => {
                if in_quotes {
                    current_field.push(c);
                } else {
                    current_field.push(c);
                }
            }
            None => {
                break;
            }
        }
    }
    // Push the last field
    fields.push(current_field);
    fields
}

/// Reads all rows from a CSV string, parsing each line.
