/// Groups rows by the value in a specified column index.
///
/// # Arguments
/// * `rows` - A vector of CSV rows.
/// * `column_index` - The index of the column to group by.
///
/// # Returns
/// A HashMap mapping column values to vectors of rows that have that value.
/// If a row doesn't have enough columns, it is skipped.
pub fn group_by_column(rows: &[CsvRow], column_index: usize) -> HashMap<String, Vec<CsvRow>> {
    let mut grouped: HashMap<String, Vec<CsvRow>> = HashMap::new();

    for row in rows {
        if column_index < row.len() {
            let key = row[column_index].clone();
            grouped.entry(key).or_insert_with(Vec::new).push(row.clone());
        }
    }

    grouped
