// Parse a single CSV line into fields, handling quoted fields
std::vector<std::string> parseCSVLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    bool inQuotes = false;
    size_t i = 0;
    size_t len = line.size();

    while (i < len) {
        char c = line[i];

        if (inQuotes) {
            if (c == '"') {
                // Check for escaped quote (double quote)
                if (i + 1 < len && line[i + 1] == '"') {
                    field += '"';
                    i += 2;
                    continue;
                } else {
                    // End of quoted field
                    inQuotes = false;
                    i++;
                    continue;
                }
            } else {
                field += c;
                i++;
            }
        } else {
            if (c == '"') {
                inQuotes = true;
                i++;
            } else if (c == ',') {
                fields.push_back(field);
                field.clear();
                i++;
            } else if (c == '\r') {
                // Skip carriage return
                i++;
            } else if (c == '\n') {
                // End of line
                fields.push_back(field);
                return fields;
            } else {
                field += c;
                i++;
            }
        }
    }

    // If we exit the loop, add the last field
    if (!field.empty() || !inQuotes) {
        fields.push_back(field);
    }

    return fields;
}

// Read all rows from a CSV file, skipping the header row
std::vector<std::vector<std::string>> readCSV(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Cannot open file: " + filename);
    }

    std::vector<std::vector<std::string>> rows;
    std::string line;
    bool isFirstLine = true;

    while (std::getline(file, line)) {
        // Skip empty lines
        if (line.empty()) {
            continue;
        }

        // Remove trailing \r if present (for Windows line endings)
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }

        if (isFirstLine) {
            // Skip header row
            isFirstLine = false;
            continue;
        }

        std::vector<std::string> fields = parseCSVLine(line);
        if (!fields.empty()) {
            rows.push_back(fields);
        }
    }

    file.close();
    return rows;
}

