use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub struct Matrix {
    data: Vec<Vec<f64>>,
    rows: usize,
    cols: usize,
}

impl Matrix {
    /// Create a new Matrix from a 2D vector
    pub fn new(data: Vec<Vec<f64>>) -> Result<Self, String> {
        if data.is_empty() {
            return Err("Matrix cannot be empty".to_string());
        }
        let rows = data.len();
        let cols = data[0].len();
        if cols == 0 {
            return Err("Matrix columns cannot be empty".to_string());
        }
        for row in &data {
            if row.len() != cols {
                return Err("All rows must have the same number of columns".to_string());
            }
        }
        Ok(Matrix {
            data,
            rows,
            cols,
        })
    }

    /// Create a zero matrix of given dimensions
    pub fn zeros(rows: usize, cols: usize) -> Self {
        let data = vec![vec![0.0; cols]; rows];
        Matrix {
            data,
            rows,
            cols,
        }
    }

    /// Get the number of rows
    pub fn rows(&self) -> usize {
        self.rows
    }

    /// Get the number of columns
    pub fn cols(&self) -> usize {
        self.cols
    }

    /// Get a reference to an element at (row, col)
    pub fn get(&self, row: usize, col: usize) -> Option<&f64> {
        if row < self.rows && col < self.cols {
            Some(&self.data[row][col])
        } else {
            None
        }
    }

    /// Multiply two matrices
    pub fn multiply(&self, other: &Matrix) -> Result<Self, String> {
        if self.cols != other.rows {
            return Err(format!(
                "Cannot multiply: {}x{} matrix cannot be multiplied by {}x{} matrix",
                self.rows, self.cols, other.rows, other.cols
            ));
        }
        let mut result = vec![vec![0.0; other.cols]; self.rows];
        for i in 0..self.rows {
            for j in 0..other.cols {
                let mut sum = 0.0;
                for k in 0..self.cols {
                    sum += self.data[i][k] * other.data[k][j];
                }
                result[i][j] = sum;
            }
        }
        Matrix::new(result)
    }

    /// Transpose the matrix
    pub fn transpose(&self) -> Self {
        let mut transposed = vec![vec![0.0; self.rows]; self.cols];
        for i in 0..self.rows {
            for j in 0..self.cols {
                transposed[j][i] = self.data[i][j];
            }
        }
        Matrix {
            data: transposed,
            rows: self.cols,
            cols: self.rows,
        }
    }
}

impl fmt::Display for Matrix {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for row in &self.data {
            writeln!(f, "{:?}", row)?;
        }
        Ok(())
    }
}

