// Matrix type and operations in TypeScript

interface Matrix {
  rows: number;
  cols: number;
  data: number[][];
}

/**
 * Creates a new matrix from a 2D array.
 */
function createMatrix(data: number[][]): Matrix {
  if (data.length === 0) {
    throw new Error("Matrix cannot have zero rows");
  }
  const rows = data.length;
  const cols = data[0].length;
  if (cols === 0) {
    throw new Error("Matrix cannot have zero columns");
  }
  // Validate all rows have the same number of columns
  for (let i = 1; i < rows; i++) {
    if (data[i].length !== cols) {
      throw new Error("All rows must have the same number of columns");
    }
  }
  return { rows, cols, data };
}

/**
 * Multiplies two matrices.
 * The number of columns in the first matrix must equal the number of rows in the second.
 */
function multiply(a: Matrix, b: Matrix): Matrix {
  if (a.cols !== b.rows) {
    throw new Error(
      `Cannot multiply: a.cols (${a.cols}) !== b.rows (${b.rows})`
    );
  }
  const resultData: number[][] = [];
  for (let i = 0; i < a.rows; i++) {
    const row: number[] = [];
    for (let j = 0; j < b.cols; j++) {
      let sum = 0;
      for (let k = 0; k < a.cols; k++) {
        sum += a.data[i][k] * b.data[k][j];
      }
      row.push(sum);
    }
    resultData.push(row);
  }
  return createMatrix(resultData);
}

/**
 * Transposes a matrix.
 * The rows become columns and columns become rows.
 */
function transpose(matrix: Matrix): Matrix {
  const { rows, cols, data } = matrix;
  const newData: number[][] = [];
  for (let j = 0; j < cols; j++) {
    const newRow: number[] = [];
    for (let i = 0; i < rows; i++) {
      newRow.push(data[i][j]);
    }
    newData.push(newRow);
  }
  return createMatrix(newData);
}

