// Item 表示优先队列中的一个元素
type Item struct {
	NodeID   int     // 节点ID
	Distance float64 // 从源点到该节点的最短距离
	Index    int     // 在堆中的索引（堆操作时需要）
}

// PriorityQueue 实现 heap.Interface 接口的最小堆
type PriorityQueue []*Item

func (pq PriorityQueue) Len() int { return len(pq) }

// 最小堆：距离小的优先级高（排在前面）
func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].Distance < pq[j].Distance
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].Index = i
	pq[j].Index = j
}

func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.Index = n
	*pq = append(*pq, item)
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil // 避免内存泄漏
	item.Index = -1
	*pq = old[0 : n-1]
	return item
}

