   use std::collections::{BinaryHeap, VecDeque}; // Actually, BinaryHeap is enough
   use std::cmp::Reverse;

   type Graph = Vec<Vec<(usize, f64)>>;

   pub fn dijkstra(graph: &Graph, start: usize) -> (Vec<f64>, Vec<Option<usize>>) {
       let n = graph.len();
       let mut dist = vec![f64::INFINITY; n];
       let mut prev = vec![None; n];
       let mut visited = vec![false; n];
       let mut heap = BinaryHeap::new();

       dist[start] = 0.0;
       heap.push(Reverse((0.0, start)));

       while let Some(Reverse((d, u))) = heap.pop() {
           if visited[u] { continue; }
           visited[u] = true;

           for &(v, weight) in &graph[u] {
               let new_dist = d + weight;
               if new_dist < dist[v] {
                   dist[v] = new_dist;
                   prev[v] = Some(u);
                   heap.push(Reverse((new_dist, v)));
               }
           }
       }

       (dist, prev)
   }
