# Dijkstra 最短路径算法 - JavaScript 实现

## 算法核心思想

Dijkstra 算法用于在**带非负权重的有向/无向图**中，从单个源节点出发，找到到所有其他节点的最短路径。它使用**贪心策略** + **优先队列（最小堆）**，每次选取当前距离最小的未访问节点进行松弛操作。

## 完整代码实现

```javascript
/**
 * Dijkstra 最短路径算法
 * @param {Object} graph - 邻接表形式的图，格式: { 节点: [{ 目标: 节点, 权重: 数值 }] }
 * @param {string} source - 源节点
 * @returns {Object} - { distances: 最短距离, previous: 前驱节点, paths: 完整路径 }
 */
function dijkstra(graph, source) {
    // 1. 初始化：所有节点距离设为无穷大，前驱节点设为 null
    const distances = {};
    const previous = {};
    const visited = new Set(); // 已确定最短路径的节点集合

    for (const node in graph) {
        distances[node] = Infinity;
        previous[node] = null;
    }
    distances[source] = 0; // 源节点到自身距离为 0

    // 2. 使用最小堆（优先队列）存储 [距离, 节点]
    //    这里用简单数组模拟，实际项目中建议使用更高效的堆结构
    const pq = [[0, source]]; // [distance, node]

    while (pq.length > 0) {
        // 取出距离最小的节点（从数组中找最小值，时间复杂度 O(n)）
        // 优化：实际可用二叉堆将取出操作降至 O(log n)
        pq.sort((a, b) => a[0] - b[0]);
        const [currentDist, currentNode] = pq.shift();

        // 如果该节点已处理过，跳过（避免重复处理）
        if (visited.has(currentNode)) {
            continue;
        }
        visited.add(currentNode);

        // 如果当前距离大于已记录的最短距离，说明是旧数据，跳过
        if (currentDist > distances[currentNode]) {
            continue;
        }

        // 3. 遍历当前节点的所有邻居，进行"松弛"操作
        const neighbors = graph[currentNode] || [];
        for (const { target, weight } of neighbors) {
            if (visited.has(target)) {
                continue; // 已处理的节点不再更新
            }

            const newDist = currentDist + weight;

            // 松弛：如果通过当前节点到达邻居的距离更短，则更新
            if (newDist < distances[target]) {
                distances[target] = newDist;
                previous[target] = currentNode;
                pq.push([newDist, target]);
            }
        }
    }

    // 4. 重构从源节点到各节点的最短路径
    const paths = {};
    for (const node in distances) {
        paths[node] = reconstructPath(previous, node, source);
    }

    return {
        distances,
        previous,
        paths
    };
}

/**
 * 根据前驱节点数组重构最短路径
 * @param {Object} previous - 前驱节点映射
 * @param {string} target - 目标节点
 * @param {string} source - 源节点
 * @returns {Array} - 从源到目标的路径节点数组
 */
function reconstructPath(previous, target, source) {
    const path = [];
    let current = target;

    // 从目标节点回溯到源节点
    while (current !== null && previous.hasOwnProperty(current)) {
        path.unshift(current);
        if (current === source) {
            break;
        }
        current = previous[current];
    }

    // 如果路径为空或源节点不在路径中，说明不可达
    if (path.length === 0 || path[0] !== source) {
        return [];
    }

    return path;
}

